class AABB {
    x: float
    y: float
    w: float
    h: float

    constructor(x: float, y: float, w: float, h: float) {
        this.x = x
        this.y = y
        this.w = w
        this.h = h
    }
}

function detectCollision(a: AABB, b: AABB): bool {
    // Check if A is left of B (touching edges are not overlap)
    if a.x + a.w < b.x {
        return false
    }
    // Check if A is right of B
    if a.x > b.x + b.w {
        return false
    }
    // Check if A is above B
    if a.y + a.h < b.y {
        return false
    }
    // Check if A is below B
    if a.y > b.y + b.h {
        return false
    }
    return true
}

