export function main(): null {
    let alive = true
    let neighbors = 1

    // Conway's Game of Life transition rule:
    // A live cell with fewer than 2 neighbors dies (underpopulation)
    // A live cell with 2 or 3 neighbors lives
    // A live cell with more than 3 neighbors dies (overpopulation)
    // A dead cell with exactly 3 neighbors becomes alive (reproduction)

    if alive {
        if neighbors < 2 {
            alive = false
        } else if neighbors > 3 {
            alive = false
        }
        // For neighbors == 2 or 3, alive stays true
    } else {
        if neighbors == 3 {
